import{z as o,x as s,o as B,c as p,q as t,j as i,D as e,d as a,s as l,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"局部波动率的实操","description":"","frontmatter":{"title":"局部波动率的实操","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-local-vol-practice.md","filePath":"quant/vt-local-vol-practice.md","lastUpdated":1791413859000}'),d={name:"quant/vt-local-vol-practice.md"};function C(c,E,u,D,F,h){const r=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=t('<h1 id="局部波动率的实操" tabindex="-1">局部波动率的实操 <a class="header-anchor" href="#局部波动率的实操" aria-label="Permalink to &quot;局部波动率的实操&quot;">​</a></h1><div class="epigraph"><p>局部波动用一个定理买到今日欧式的全部贴合，代价是把未来的微笑写成平的；实操的全部功夫，在于知道哪些产品付不起这个代价。</p><footer>—— 据 Dupire, 1994；Gyöngy, 1986 整理</footer></div><p><a href="/quant/vt-sv-calibration-deep">上一课</a>把随机波动校准钉进管线；但 SV 家族贴不满全部执行价，前瞻微笑也常不对。本课把 Dupire 局部波动落成日常引擎。<a href="/quant/dupire-calib">Dupire 局部波动校准</a>讲了反问题与病态性；本课讲生产侧：插值、外推、引擎分工与动态性验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dupire 公式要对总方差 \\(w(k,T)\\) 求时间导数与对执行价的二阶差分，对报价噪声极端敏感；离散到期日之间的插值假设直接改变障碍价；外推的翼部决定极端情景的价格。跳过这三件事得到的局部波动表面照样光滑，但价格是插值假设的产物，不是市场的产物——实操的第一课是承认：局部波动的输出质量由上游的曲面工程决定，不由公式决定。</p><p><span class="marginnote">术语翻译：局部波动就是把波动写成「标的价格与时间」的函数 \\(\\sigma(S,t)\\)——价格走到哪一格，波动取哪个数，是一条事先铺好的轨道。它今天能完美贴合全部欧式报价，但轨道本身未必像真实世界。</span></p><h3 id="管线五步" tabindex="-1">管线五步 <a class="header-anchor" href="#管线五步" aria-label="Permalink to &quot;管线五步&quot;">​</a></h3><p>一、无套利化：先把报价参数化成 <a href="/quant/svi-ssvi">SVI/SSVI</a> 并做蝶式与日历扫描，绝不对原始报价二阶差分。二、抽局部波动：时间导数按插值假设给出，空间用正则化或 <a href="/quant/dupire-calib">Andreasen–Huge 正向差分</a>；分母近零处切断并记录切断位置——它就是模型的自认边界。三、外推：翼部按 SVI 的渐近斜率走，尾部检查密度非负。四、引擎分工：美式与百慕大行权（<a href="/quant/american-exercise">美式期权与提前行权</a>）、障碍与触碰（<a href="/quant/barrier-analytics">障碍解析</a>）交给局部波动做一致性重估；欧式精合交给参数模型；远期微笑敏感的产品升级到<a href="/quant/lsv-hybrid-calib">局部-随机混合</a>。五、验收：同一香草集上，局部波动价格与市场价误差必须小于一个最小变动价位，然后才有资格谈其他产品的输出。</p>',8)),(B(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IV%5B%22%E9%9A%90%E5%90%AB%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20ARB%5B%22SVI%20%E6%97%A0%E5%A5%97%E5%88%A9%E5%8C%96%E4%B8%8E%E6%89%AB%E6%8F%8F%22%5D%0A%20%20ARB%20--%3E%20LV%5B%22%E5%B1%80%E9%83%A8%E6%B3%A2%E5%8A%A8%E6%B1%82%E8%A7%A3%EF%BC%9A%E6%AD%A3%E5%88%99%E4%B8%8E%E5%88%87%E6%96%AD%22%5D%0A%20%20LV%20--%3E%20ENG%5B%22%E4%B8%80%E8%87%B4%E6%80%A7%E5%BC%95%E6%93%8E%EF%BC%9A%E7%BE%8E%E5%BC%8F%20%E9%9A%9C%E7%A2%8D%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20ENG%20--%3E%20DYND%7B%22%E5%8A%A8%E6%80%81%E6%80%A7%E8%AF%8A%E6%96%AD%22%7D%0A%20%20DYND%20--%3E%7C%22%E8%BF%9C%E6%9C%9F%E5%BE%AE%E7%AC%91%E5%B9%B3%E5%9D%A6%E8%AD%A6%E5%91%8A%22%7C%20ESC%5B%22%E8%BF%9C%E6%9C%9F%E6%95%8F%E6%84%9F%E5%93%81%E5%8D%87%E7%BA%A7%20LSV%22%5D%0A%20%20DYND%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20USE%5B%22%E6%AC%A7%E5%BC%8F%20SV%20%2F%20%E8%B7%AF%E5%BE%84%20LV%20%E5%88%86%E5%B7%A5%E8%A1%A8%22%5D%0A%20%20LV%20--%3E%20CHECK%5B%22%E9%A6%99%E8%8D%89%E9%9B%86%E8%AF%AF%E5%B7%AE%E5%B0%8F%E4%BA%8E%E4%B8%80%E6%A1%A3%22%5D%0A%20%20CHECK%20--%3E%20ENG%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("为什么局部波动「今日全对、明天就错」：Gyöngy 的模仿定理说，局部波动复制的是随机波动的单期边际分布，不是它的联合动态。于是欧式贴合是定理保证的，前瞻微笑平坦是同一枚硬币的反面——"),A("a",{href:"/quant/cliquet-forward-start"},"远期起始与 cliquet"),a(" 因此被系统性错价。对冲侧有一条互补结论：El Karoui、Jeanblanc 与 Shreve 证明，扩散世界里用错成局部波动的 Black–Scholes 对冲有一致的良好上界，跳一进来界就破。所以局部波动的舒适区是扩散主导的指数香草与短日期权，不是跳主导的个股长障碍。")],-1)),(B(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%80%E4%B8%AA%E4%BA%A7%E5%93%81%E8%A6%81%E8%B5%B0%E5%B1%80%E9%83%A8%E6%B3%A2%E5%8A%A8%E5%BC%95%E6%93%8E%22%5D%20--%3E%20Q1%5B%22%E6%A0%87%E7%9A%84%E6%98%AF%E6%89%A9%E6%95%A3%E4%B8%BB%E5%AF%BC%E8%BF%98%E6%98%AF%E8%B7%B3%E4%B8%BB%E5%AF%BC%3F%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%8C%87%E6%95%B0%E9%A6%99%E8%8D%89%E3%80%81%E7%9F%AD%E6%9C%9F%E9%99%90%22%7C%20OK%5B%22%E5%AF%B9%E5%86%B2%E8%AF%AF%E5%B7%AE%E6%9C%89%E4%B8%80%E8%87%B4%E4%B8%8A%E7%95%8C%3A%E8%88%92%E9%80%82%E5%8C%BA%22%5D%0A%20%20Q1%20--%3E%7C%22%E8%B7%B3%E4%B8%BB%E5%AF%BC%E7%9A%84%E4%B8%AA%E8%82%A1%E9%95%BF%E9%9A%9C%E7%A2%8D%22%7C%20NO%5B%22%E8%B7%B3%E4%B8%80%E8%BF%9B%E6%9D%A5%2C%E5%AF%B9%E5%86%B2%E4%B8%8A%E7%95%8C%E5%B0%B1%E7%A0%B4%22%5D%0A%20%20NO%20--%3E%20ESC%5B%22%E5%8D%87%E7%BA%A7%20LSV%20%E6%88%96%E6%94%B9%E7%94%A8%E6%83%85%E6%99%AF%E9%99%90%E9%A2%9D%22%5D%0A%20%20OK%20--%3E%20KEEP%5B%22%E5%8F%AF%E7%94%A8%2C%E4%BD%86%E8%BF%9C%E6%9C%9F%E5%BE%AE%E7%AC%91%E6%95%8F%E6%84%9F%E5%93%81%E9%99%A4%E5%A4%96%22%5D%0A%20%20KEEP%20--%3E%20CHECK%5B%22%E8%BF%9C%E6%9C%9F%E8%B5%B7%E5%A7%8B%E4%B8%8E%20cliquet%20%E5%85%88%E6%9F%A5%E5%89%8D%E7%9E%BB%E5%BE%AE%E7%AC%91%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">局部波动会把「未来 ATM 波动先跌后涨」读成今天曲面上的斜率与曲率，远期起始与 cliquet 的价因此整体偏移。验收清单里永远要有一条「远期微笑是否平坦」：答案是平坦时，这一类产品不许用纯局部波动报价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日常运维三条。第一，插值假设写成文档：到期之间的方差按什么插（总方差线性、总隐波线性），障碍价对选择的敏感度每年至少测一次。第二，切断位置与正则强度进版本管理：局部波动表面的每次重生成，都要能回答「哪里变了、为什么变」。第三，与 SV 的价差当模型带报告：同一香草集两个引擎的价格差不是误差，是模型不确定性的带宽，带宽突然扩大本身就是诊断信号——通常是曲面出了局部病态。</p><p><span class="marginnote">常见误区：初学者把「表面重新生成后看着差不多」当成没变化。两条表面差半个波动点，长障碍期权的价格可以差出一位数百分比——所以切断位置与正则强度必须像代码一样进版本管理、可回滚。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 Dupire 公式，粒子法校准 LSV 在混合校准课；股息与提前行权的耦合只点名不展开。最后一条边界留给下一课：局部波动与 SV 的分歧是「模型带」，但奇异账本要的是把带宽变成限额——哪类产品的带宽不可接受、用什么情景看着它，是奇异风控收束课的内容。</p><p><span class="marginnote">直觉类比：LV 与 SV 的价差像两位测绘员对同一座山报的不同海拔——差别不是谁错了，而是「测不准的那部分」有多大。模型带宽就是这份不确定性的标价，交易与限额都要为它留出余量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>局部波动的输出质量由上游曲面工程决定：无套利化、插值、外推三件先做对。</li><li>切断位置是模型的自认边界，正则强度进版本管理，可追溯。</li><li>Gyöngy 定理是硬币两面：欧式贴合与前瞻微笑平坦同源。</li><li>舒适区是扩散主导的指数香草与短障碍；跳主导的个股长障碍不在此列。</li><li>与 SV 的价差当模型带报告，带宽突变本身是诊断信号。</li><li>出处：Dupire, 1994；Gyöngy, 1986；El Karoui, Jeanblanc and Shreve, 1998；数值细节见 Dupire 校准课。</li></ul>',9))])}const S=o(d,[["render",C]]);export{f as __pageData,S as default};
